def main():
    paths = json.loads((ROOT/'work/light-shadow-paths.json').read_text(encoding='utf-8'))
    chosen = [p for p in paths if re.search(r'\b(light|shadows?|reflection|refraction)\b',p['topic'],re.I) and p['subject'].lower()=='science']
    groups={}
    for p in chosen:groups.setdefault((p['level'],p['topic']),[]).append(p)
    DEST.mkdir(parents=True,exist_ok=True)
    manifest=[]
    for (level,topic),linked in sorted(groups.items()):
        names=list(dict.fromkeys(s['name'] for p in linked for s in p['subtopics']))
        data=dict(title=topic+' · Discovery Lab',level=level,lessons=[lesson(n,topic) for n in names])
        filename=uuid5(NAMESPACE_URL,'flame:light-shadow:'+level+':'+topic+':2026-10-12').hex+'.html'
        payload=PAGE.replace('__TITLE__',html.escape(data['title'])).replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
        (DEST/filename).write_text(payload,encoding='utf-8')
        manifest.append(dict(title=data['title'],type='interactive',file=str(DEST/filename),grade_min=int(re.search(r'\d+',level)[0]),grade_max=int(re.search(r'\d+',level)[0]),purposes=['explain','demonstrate'],teaching_languages=['en'],concepts=[topic],subtopics=names,paths=linked))
    (ROOT/'project-stages/LIGHT-SHADOW-INTERACTIVES.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
    guide=['# Light and Shadow HTML5 activities','', 'Created 2026-10-12. Self-contained instructional activities; no network calls or external assets. Files are stored in the configured private Interactive folder. Files have not been registered, mapped or published in the Resource Library. Upload/paste them through the existing editor when ready.','', 'Each file covers its listed subtopics through an explanation, an experiment instruction, interactive controls, observed feedback and a short check. Diagrams are simplified and labelled. Grade 1 Light and Shadow lessons and Grade 4 optics are included, along with Grade 1 light/sound-signal topics. The inventory excludes plant biology, weather rain-shadow and standalone Sound topics.','', '| Grade | Activity | Subtopics | File |','| --- | --- | --- | --- |']
    for m in manifest:guide.append(f"| {m['grade_min']} | {m['title']} | {len(m['subtopics'])} | [Open HTML]({m['file'].replace(chr(92),'/')}) |")
    guide+=['','## Import and mapping','', 'The JSON companion records exact curriculum topic/subtopic IDs for FlipLecture and TN Stateboard where present. It is a coverage manifest, not a bulk-import workbook. Map the matching grade/topic after creating each resource; individual subtopic mappings are optional if the whole activity serves the topic. Metadata suggestions include explain/demonstrate, English and the matching grade. Review content, accessibility and rights before publication. Google Sheets does not transfer HTML bytes.','', 'Interactive files work with FLAME’s sandboxed HTML viewer. Open a file locally for author review, or upload/paste it into Resource Library and use Preview. No real student progress is recorded. Source builder: interactive-sources/build_light_shadow.py; its input is the read-only work/light-shadow-paths.json curriculum inventory.']
    (ROOT/'project-stages/LIGHT-SHADOW-INTERACTIVES.md').write_text('\n'.join(guide)+'\n',encoding='utf-8')
    print(f'Created {len(manifest)} HTML files, covering {sum(len(m["subtopics"]) for m in manifest)} lesson entries and {len(chosen)} curriculum paths.')


if __name__=='__main__':main()
